mapper.select:
select *
from IBMMQ_QUEUE_DATA
where MONITOR_ID = #{monitorId}
  and CAPTURETIME = (
    select max(CAPTURETIME)
    from IBMMQ_QUEUE_DATA
    where MONITOR_ID = #{monitorId}
)

select *
from IBMMQ_CHANNEL_DATA
where MONITOR_ID = #{monitorId}
  and CAPTURETIME = (
    select max(CAPTURETIME)
    from IBMMQ_CHANNEL_DATA
    where MONITOR_ID = #{monitorId}
)
